import sympy
from sympy import eye, zeros, Rational, Integer
from sympy.combinatorics.named_groups import SymmetricGroup, AlternatingGroup, DihedralGroup, CyclicGroup

S3 = SymmetricGroup(3)
S4 = SymmetricGroup(4)
A4 = AlternatingGroup(4)
D4 = DihedralGroup(4)
C4 = CyclicGroup(4)
V4 = AlternatingGroup(4)
Z2 = CyclicGroup(2)
Z3 = CyclicGroup(3)
Z4 = CyclicGroup(4)
Z6 = CyclicGroup(6)
trivial = CyclicGroup(1)

I2 = eye(2)
I3 = eye(3)
O2 = zeros(2, 2)
O3 = zeros(3, 3)

CONDITION_LABELS = [
    "H_1: n is an integer with n >= 2",
    "¬Q: The ideal generated by the variables in the polynomial ring is a principal ideal"
]

N_HYP = 1
NEG_Q_INDEX = 1

def conditions(witness):
    try:
        if isinstance(witness, dict):
            F = witness.get('F')
            n = witness.get('n')
        elif isinstance(witness, (tuple, list)) and len(witness) == 2:
            F, n = witness
        else:
            F, n = None, witness
    except Exception:
        F, n = None, None

    try:
        h1 = isinstance(n, (int, Integer)) and n >= 2
    except Exception:
        h1 = False

    try:
        if F is None:
            neg_q = False
        elif isinstance(F, int):
            neg_q = (F in (0, 1))
        elif isinstance(F, str):
            neg_q = F.strip().lower() in ("0", "1", "z/1z", "z_1", "trivial", "zero", "zero ring")
        elif hasattr(F, 'zero') and hasattr(F, 'one'):
            neg_q = (F.zero == F.one)
        elif F is trivial:
            neg_q = True
        else:
            neg_q = bool(F == 0)
    except Exception:
        neg_q = False

    return [h1, neg_q]